#!/usr/bin/env node
/**
 * Registers local git merge drivers referenced by .gitattributes.
 *
 * `merge` driver names in .gitattributes are not self-describing — each one
 * must also be registered in git config (repo-local, not committable) before
 * git will use it instead of its default line-based 3-way merge. This runs
 * on every `pnpm install` (see postinstall-security.js) so the registration
 * exists in every clone/worktree/CI checkout without a manual setup step.
 *
 * `mcp-generated-ours`: used for docs/mcp/api-reference.html (LS-10150).
 * That file is wholly regenerated by every MCP-touching PR, so two PRs in
 * flight always conflict on it even though neither actually disagrees about
 * content — the disagreement is with whatever else has since landed on
 * main. `driver = true` is the standard trick for "always take our side,
 * never conflict": the driver command runs, does nothing to the merged
 * file, and its exit code (0, from the `true` command) tells git the merge
 * succeeded. This is safe here specifically because the file is generated,
 * not authored, and its own CI gate (mcp-api-reference-sync.sh) fails the
 * build if the checked-in file doesn't match a fresh regeneration, so a
 * stale "ours" from before the merge is still caught before it can land.
 */
const { execFileSync } = require('child_process');

function gitConfig(key, value) {
  execFileSync('git', ['config', key, value], { stdio: 'ignore' });
}

try {
  gitConfig('merge.mcp-generated-ours.driver', 'true');
} catch (error) {
  console.warn(
    `⚠️  Could not register git merge driver 'mcp-generated-ours': ${error.message}`,
  );
}
